[HarmonyPatch]
public static class NeowCurseOptionsPatch
{
	[HarmonyTargetMethod]
	public static MethodBase Target(HarmonyPatchType p, Harmony instance)
	{
		return AccessTools.PropertyGetter(typeof(Neow), "CurseOptions");
	}

	private static void Postfix(Neow __instance, ref IEnumerable<EventOption> __result)
	{
		List<EventOption> list = __result.ToList();
		if (ThingsModConfig.IsEnabled("NeowRelicCurseRemoverEnabled"))
		{
			AddRelicToList<ThingsCurseRemover>(__instance, list);
		}
		if (ThingsModConfig.IsEnabled("NeowRelicWhiteFlagEnabled"))
		{
			AddRelicToList<ThingsWhiteFlag>(__instance, list);
		}
		if (ThingsModConfig.IsEnabled("NeowRelicMagicGloveEnabled"))
		{
			AddRelicToList<ThingsMagicGlove>(__instance, list);
		}
		if (list.Any((EventOption option) => option.Relic is ThingsMagicGlove))
		{
			list.RemoveAll(delegate(EventOption option)
			{
				RelicModel relic = option.Relic;
				return ((relic != null) ? ((AbstractModel)relic).Id.Entry : null) == "PRECARIOUS_SHEARS";
			});
		}
		__result = list;
	}

	private static void AddRelicToList<T>(Neow neow, List<EventOption> list) where T : RelicModel
	{
		//IL_0075: Unknown result type (might be due to invalid IL or missing references)
		Neow neow2 = neow;
		RelicModel relic = ((RelicModel)ModelDb.Relic<T>()).ToMutable();
		Player owner = ((EventModel)neow2).Owner;
		if (owner != null)
		{
			relic.Owner = owner;
		}
		EventOption item = new EventOption((EventModel)(object)neow2, (Func<Task>)async delegate
		{
			Player val = ((EventModel)neow2).Owner ?? throw new InvalidOperationException("Neow relic option was selected without an event owner.");
			await RelicCmd.Obtain(relic, val, -1);
			typeof(AncientEventModel).GetMethod("Done", BindingFlags.Instance | BindingFlags.NonPublic)?.Invoke(neow2, null);
		}, relic.Title, relic.DynamicEventDescription, "INITIAL", relic.HoverTipsExcludingRelic).WithRelic(relic);
		list.Add(item);
	}
}
