		internal static IReadOnlyList<CutoutBoneSpec> GetBones(string key)
		{
			return key switch
			{
				"origin_fogmog" => OriginFogmogBones, 
				"bowlbug_progenitor" => BowlbugProgenitorBones, 
				"scale_beetle" => ScaleBeetleBones, 
				"soul_roe_1" => SoulRoe1Bones, 
				"soul_roe_2" => SoulRoe2Bones, 
				"soul_roe_3" => SoulRoe3Bones, 
				"soul_roes" => SoulRoesBones, 
				"the_legacy" => TheLegacyBones, 
				_ => throw new KeyNotFoundException("Unknown cutout rig key: " + key), 
			};
		}

		internal static IReadOnlyList<CutoutPartSpec> Get(string key)
		{
			return key switch
			{
				"origin_fogmog" => OriginFogmog, 
				"bowlbug_progenitor" => BowlbugProgenitor, 
				"scale_beetle" => ThingsScaleBeetle, 
				"soul_roe_1" => SoulRoe1, 
				"soul_roe_2" => SoulRoe2, 
				"soul_roe_3" => SoulRoe3, 
				"soul_roes" => SoulRoes, 
				"the_legacy" => ThingsTheLegacy, 
				_ => throw new KeyNotFoundException("Unknown cutout rig key: " + key), 
			};
		}
	}
