			_cts?.Cancel();
			_cts?.Dispose();
			_cts = new CancellationTokenSource();
			if (!animBase.StartsWith("grab_player") && (HasCapturedPlayers || _isGrabTracking))
			{
				RestoreCapturedPlayersInstantly();
			}
			if (_armsNode != null)
			{
				_armsNode.Scale = new Vector2(1.3f, 1.3f);
			}
			if (animBase.StartsWith("grab_player") || animBase.StartsWith("grab_slam"))
			{
				_isRightGrab = isFlipped || animBase.Contains("right");
			}
			if (isFlipped)
			{
				switch (animBase)
				{
				case "front_sweep":
					animBase = "front_sweep_right";
					break;
				case "front_sweep_angry":
					animBase = "front_sweep_right_angry";
					break;
				case "grab_player":
					animBase = "grab_player_right";
					break;
				case "grab_player_angry":
					animBase = "grab_player_right_angry";
					break;
				case "grab_slam":
					animBase = "grab_slam_right";
					break;
				case "grab_slam_angry":
					animBase = "grab_slam_right_angry";
					break;
				case "leftpunch":
					animBase = "rightpunch";
					break;
				case "weak_attack":
					animBase = "weak_attack_right";
					break;
				case "weak_enter":
					animBase = "weak_enter_right";
					break;
				case "weak_idle":
					animBase = "weak_idle_right";
					break;
				case "weak_recover":
					animBase = "weak_recover_right";
					break;
				}
			}
			string text = animBase;
			if (_isAngry)
			{
				if (!text.EndsWith("_angry"))
				{
					string text2 = animBase + "_angry";
					if (_bodyController != null && HasBossAnimation(_bodyController, text2))
					{
						text = text2;
					}
				}
			}
			else if (text.EndsWith("_angry"))
			{
				text = text.Substring(0, text.Length - "_angry".Length);
			}
			string animName = (_isAngry ? "idle_front_angry" : "idle_front");
			PrepareContactAim(text);
			SetTrackAnimationBoth(text, loop: false, 0);
			if (!animBase.StartsWith("grab_player"))
			{
				AddTrackAnimationBoth(animName, 0f, loop: true, 0);
			}
			Log.Info($"[CaveGodBackground] Started attack animation: {text} (isAngry={_isAngry}, isFlipped={isFlipped})", 2);
		}

