		public void PlayHurtAnim(bool forceGroan = false, Vector2? hitPos = null)
		{
			if (_isRetreating)
			{
				return;
			}
			ulong ticksMsec = Time.GetTicksMsec();
			if (forceGroan || ticksMsec - _lastHurtAnimTicks >= 150)
			{
				_lastHurtAnimTicks = ticksMsec;
				if (_isGrabTracking)
				{
					PlayGrabHurtFeedback(hitPos, forceGroan);
				}
				else if (!_isWeakIdle)
				{
					string hurtTrackAnimationBoth = (_isAngry ? "hit_recoil_angry" : "hit_recoil");
					SetHurtTrackAnimationBoth(hurtTrackAnimationBoth);
					PlayHurtGroan(forceGroan);
				}
				else
				{
					PlayWeakHurtAnim(hitPos, forceGroan);
				}
			}
		}

