			{
				return BoneRole.Root;
			}
			if (name.Contains("Head", StringComparison.Ordinal) || name.Contains("Face", StringComparison.Ordinal) || name.Contains("Cap", StringComparison.Ordinal) || name.Contains("Antenna", StringComparison.Ordinal) || name.Contains("Jaw", StringComparison.Ordinal))
			{
				return BoneRole.Head;
			}
			if (name.Contains("Left", StringComparison.Ordinal) || name.Contains("Front", StringComparison.Ordinal) || x < 0f)
			{
				return BoneRole.Left;
			}
			if (name.Contains("Right", StringComparison.Ordinal) || name.Contains("Rear", StringComparison.Ordinal) || x > 0f)
			{
				return BoneRole.Right;
			}
			return BoneRole.Core;
		}

