		private float GetActionPersonalityScale()
		{
			RigPersonalityType rigPersonality = RigPersonality;
			string action = _action;
			switch (rigPersonality)
			{
			case RigPersonalityType.OriginFogmog:
				if (!(action == "Cast"))
				{
					break;
				}
				return 1f;
			case RigPersonalityType.BowlbugProgenitor:
				if (!(action == "Cast"))
				{
					break;
				}
				return 1.18f;
			case RigPersonalityType.SoulRoe:
				if (action == "Dead" || action == "Revive")
				{
					return 0.58f;
				}
				return 0.92f;
			case RigPersonalityType.ThingsTheLegacy:
				if (!(action == "Cast"))
				{
					break;
				}
				return 1f;
			case RigPersonalityType.SoulRoes:
				return 1.12f;
			}
			return 1f;
		}

		private int GetSoulRoeVariant()
		{
			float num = Mathf.PosMod(IdlePhaseOffset, (float)Math.PI * 2f);
			if (num < 1f)
			{
				return 0;
			}
			if (!(num < 3.3f))
			{
				return 2;
			}
			return 1;
		}

