		}

		internal CardModel? SelectCardToSteal(Player player)
		{
			List<CardModel> list = (from c in CardPile.GetCards(player, (PileType[])(object)new PileType[2]
				{
					(PileType)1,
					(PileType)3
				})
				where c.DeckVersion != null
				select c).ToList();
			if (list.Count == 0)
			{
				list = (from c in CardPile.GetCards(player, (PileType[])(object)new PileType[1] { (PileType)2 })
					where c.DeckVersion != null
					select c).ToList();
