				RuntimeHelpers.InitializeArray(array, (RuntimeFieldHandle)/*OpCode not supported: LdMemberToken*/);
				list = CardPile.GetCards(player, (PileType[])(object)array).ToList();
			}
			if (list.Count == 0)
			{
				return null;
			}
			IEnumerable<CardModel> source = list;
			Func<CardModel, bool>[] stealPriorities = StealPriorities;
			foreach (Func<CardModel, bool> predicate in stealPriorities)
			{
				List<CardModel> list2 = list.Where(predicate).ToList();
				if (list2.Count > 0)
				{
					source = list2;
					break;
				}
			}
			List<CardModel> list3 = source.ToList();
			RunRngSet runRng = ((MonsterModel)this).RunRng;
			if (((runRng != null) ? runRng.CombatCardGeneration : null) == null)
			{
				return list3[0];
			}
			return ((MonsterModel)this).RunRng.CombatCardGeneration.NextItem<CardModel>((IEnumerable<CardModel>)list3);
		}

		public async Task ReleaseStolenCards()
		{
