			List<CardModel> list = _stolenCards.ToList();
			_stolenCards.Clear();
			ClearStolenCardVisual();
			foreach (CardModel card in list)
			{
				Player owner = card.Owner;
				Creature val = ((owner != null) ? owner.Creature : null);
				if (val != null && val.IsAlive)
				{
					card.HasBeenRemovedFromState = false;
					try
