						await CardPileCmd.Add(card, (PileType)2, (CardPilePosition)1, (AbstractModel)null, false);
					}
					catch (Exception ex)
					{
						Log.Warn($"[CaveGodHand] Failed to return stolen card {((AbstractModel)card).Id} to Hand ({ex.Message}), falling back to Discard pile.", 2);
						try
						{
							card.HasBeenRemovedFromState = false;
							await CardPileCmd.Add(card, (PileType)3, (CardPilePosition)1, (AbstractModel)null, false);
						}
						catch (Exception ex2)
						{
							Log.Error($"[CaveGodHand] Failed to return stolen card {((AbstractModel)card).Id} to Discard pile ({ex2.Message}).", 2);
						}
					}
				}
				else
				{
					card.HasBeenRemovedFromState = false;
				}
			}
		}

