	public sealed class QuirkyHopperRewardPolicy : ModifierModel
	{
		public override bool TryModifyRewardsLate(Player player, List<Reward> rewards, AbstractRoom? room)
		{
			CombatRoom val = (CombatRoom)(object)((room is CombatRoom) ? room : null);
			if (val == null || !(val.Encounter is QuirkyHopperWeak))
			{
				return false;
			}
			List<Reward> value;
			IReadOnlyList<Reward> source = (val.ExtraRewards.TryGetValue(player, out value) ? value : new List<Reward>());
			List<PotionReward> returnedPotionRewards = source.OfType<PotionReward>().ToList();
			if (returnedPotionRewards.Count == 0)
			{
				return false;
			}
			List<PotionReward> list = (from reward in rewards.OfType<PotionReward>()
				where !returnedPotionRewards.Any((PotionReward returned) => returned == reward)
				select reward).ToList();
			foreach (PotionReward item in list)
			{
				rewards.Remove((Reward)(object)item);
			}
			return list.Count > 0;
		}
	}
	public sealed class SpentEmberRestPolicy : ModifierModel
	{
		public override bool TryModifyRestSiteOptions(Player player, ICollection<RestSiteOption> options)
		{
			BorrowedEmber relic = player.GetRelic<BorrowedEmber>();
			if (relic == null || !relic.IsSpentCampHere)
			{
				return false;
			}
			options.Clear();
			options.Add((RestSiteOption)(object)new SpentEmberRestSiteOption(player));
			return true;
		}
	}
