		InsufficientGold
	}
	public static class Crossroads
	{
		public static event Action<IRunState>? Changed;

		public static ThingsCrossroads? Ledger(IRunState run)
		{
			return run.Modifiers.OfType<ThingsCrossroads>().FirstOrDefault();
		}

		public static async Task<CrossroadPurchaseResult> Purchase(Player payer, int act, ulong fingerprint, MapCoord from, MapCoord to, int quotedPrice)
		{
			//IL_0026: Unknown result type (might be due to invalid IL or missing references)
			//IL_0027: Unknown result type (might be due to invalid IL or missing references)
			//IL_002e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0030: Unknown result type (might be due to invalid IL or missing references)
			IRunState runState = payer.RunState;
			RunState run = (RunState)(object)((runState is RunState) ? runState : null);
			if (run == null || !run.Players.Contains(payer))
			{
				return CrossroadPurchaseResult.Stale;
			}
			if (run.CurrentActIndex != act || quotedPrice != 50 || run.Map == null || CrossroadPlan.Fingerprint(run.Map) != fingerprint)
			{
				return CrossroadPurchaseResult.Stale;
			}
			MapCoord? currentMapCoord = run.CurrentMapCoord;
			MapCoord val = from;
			if (!currentMapCoord.HasValue || currentMapCoord.GetValueOrDefault() != val || run.VisitedMapCoords.Contains(to))
			{
				return CrossroadPurchaseResult.NotAtRoad;
			}
			ThingsCrossroads ledger = Ledger((IRunState)(object)run);
			CrossroadRecord crossroadRecord = (ledger?.EnsurePlan(run, run.Map, act))?.Roads.FirstOrDefault((CrossroadRecord r) => r.Touches(from) && r.Other(from) == to);
			if (crossroadRecord == null)
			{
				return CrossroadPurchaseResult.Stale;
			}
			if (crossroadRecord.IsOpen)
			{
				return CrossroadPurchaseResult.AlreadyOpen;
			}
			MapPoint source = run.Map.GetPoint(from);
			if (source != null)
			{
				MapPoint destination = run.Map.GetPoint(to);
				if (destination != null && !source.Children.Contains(destination) && !destination.Children.Contains(source))
				{
					if (payer.Gold < 50)
					{
						return CrossroadPurchaseResult.InsufficientGold;
					}
					crossroadRecord.FromColumn = from.col;
					crossroadRecord.Payer = payer.NetId;
					await PlayerCmd.LoseGold(50m, payer, (GoldLossType)1);
					source.AddChildPoint(destination);
					ledger.Commit();
					Crossroads.Changed?.Invoke((IRunState)(object)run);
					return CrossroadPurchaseResult.Purchased;
				}
			}
			return CrossroadPurchaseResult.Stale;
		}
	}
