	public enum MerchantBargainRoundResult
	{
		Tie,
		PlayerWon,
		MerchantWon
	}
	public static class MerchantBargainRules
	{
		public const int MaximumGoldShortfall = 20;

		public const int TriggerAttempt = 5;

		public static bool IsEligibleShortfall(int price, int gold)
		{
			if (price > gold)
			{
				return price - gold <= 20;
			}
			return false;
		}

		public static MerchantBargainRoundResult EvaluateRound(RelicPickingFightMove playerMove, RelicPickingFightMove merchantMove)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			//IL_0008: Unknown result type (might be due to invalid IL or missing references)
			//IL_000a: Unknown result type (might be due to invalid IL or missing references)
			//IL_000b: Unknown result type (might be due to invalid IL or missing references)
			if (playerMove == merchantMove)
			{
				return MerchantBargainRoundResult.Tie;
			}
			if ((RelicPickingFightMove)((merchantMove + 1) % 3) != playerMove)
			{
				return MerchantBargainRoundResult.MerchantWon;
			}
			return MerchantBargainRoundResult.PlayerWon;
		}
	}
	public enum MerchantBargainAttemptDisposition
	{
		PassThrough,
		Suppress,
		StartFight,
		PurchaseAtNegotiatedPrice
	}
	public sealed class MerchantBargainSession<TEntry> where TEntry : class
	{
		private readonly Dictionary<TEntry, int> _eligibleAttemptCounts = new Dictionary<TEntry, int>(ReferenceEqualityComparer.Instance);

		public bool Consumed { get; private set; }

		public bool FightInProgress { get; private set; }

		public TEntry? WinningEntry { get; private set; }

		public int? WinningPrice { get; private set; }

		public MerchantBargainAttemptDisposition RegisterAttempt(TEntry entry, bool isStocked, bool isEligible)
		{
			if (FightInProgress)
			{
				return MerchantBargainAttemptDisposition.Suppress;
			}
			if (WinningEntry != null)
			{
				if (!isStocked || WinningEntry != entry)
				{
					return MerchantBargainAttemptDisposition.PassThrough;
				}
				return MerchantBargainAttemptDisposition.PurchaseAtNegotiatedPrice;
			}
			if (Consumed || !isStocked || !isEligible)
			{
				return MerchantBargainAttemptDisposition.PassThrough;
			}
			_eligibleAttemptCounts.TryGetValue(entry, out var value);
			int num = Math.Min(value + 1, 5);
			_eligibleAttemptCounts[entry] = num;
			if (num < 5)
			{
				return MerchantBargainAttemptDisposition.PassThrough;
			}
			FightInProgress = true;
			return MerchantBargainAttemptDisposition.StartFight;
		}

		public int GetEligibleAttemptCount(TEntry entry)
		{
			return _eligibleAttemptCounts.GetValueOrDefault(entry);
		}

		public void MarkFightWon(TEntry entry, int negotiatedPrice)
		{
			ArgumentOutOfRangeException.ThrowIfNegative(negotiatedPrice, "negotiatedPrice");
			WinningEntry = entry;
			WinningPrice = negotiatedPrice;
		}

		public void MarkFightLost()
		{
			Consumed = true;
			ClearWinningOffer();
		}

		public void MarkPurchaseSucceeded()
		{
			Consumed = true;
			ClearWinningOffer();
		}

		public void ResetFightAfterError(TEntry entry)
		{
			ClearWinningOffer();
			_eligibleAttemptCounts[entry] = 4;
		}

		public void EndFight()
		{
			FightInProgress = false;
		}

		private void ClearWinningOffer()
		{
			WinningEntry = null;
			WinningPrice = null;
		}
	}
