	public struct ThingsConfigSnapshotMessage : INetMessage, IPacketSerializable
	{
		public const int Protocol = 1;

		public static readonly uint Schema = BinaryPrimitives.ReadUInt32LittleEndian(SHA256.HashData(Encoding.UTF8.GetBytes(string.Join("|", ThingsModConfig.Entries.Select((ThingsModConfig.Entry entry) => entry.Key + ":" + entry.Default.GetType().Name)))));

		public int Version;

		public uint SchemaHash;

		public uint Revision;

		public bool Locked;

		public int[] Values;

		public bool ShouldBroadcast => false;

		public NetTransferMode Mode => (NetTransferMode)2;

		public LogLevel LogLevel => (LogLevel)2;

		public bool ShouldBuffer => false;

		public void Serialize(PacketWriter writer)
		{
			writer.WriteInt(Version, 32);
			writer.WriteUInt(SchemaHash, 32);
			writer.WriteUInt(Revision, 32);
			writer.WriteBool(Locked);
			writer.WriteByte((byte)Values.Length, 8);
			int[] values = Values;
			foreach (int num in values)
			{
				writer.WriteInt(num, 32);
			}
		}

		public void Deserialize(PacketReader reader)
		{
			Values = Array.Empty<int>();
			if (reader.Buffer.Length * 8 - reader.BitPosition < 105)
			{
				return;
			}
			Version = reader.ReadInt(32);
			SchemaHash = reader.ReadUInt(32);
			Revision = reader.ReadUInt(32);
			Locked = reader.ReadBool();
			int num = reader.ReadByte(8);
			if (num == ThingsModConfig.Entries.Count && reader.Buffer.Length * 8 - reader.BitPosition >= num * 32)
			{
				Values = new int[num];
				for (int i = 0; i < num; i++)
				{
					Values[i] = reader.ReadInt(32);
				}
			}
		}

		public bool IsValid()
		{
			if (Version != 1 || SchemaHash != Schema || Revision == 0 || Values?.Length != ThingsModConfig.Entries.Count)
			{
				return false;
			}
			HashSet<string> hashSet = new HashSet<string>();
			for (int i = 0; i < Values.Length; i++)
			{
				ThingsModConfig.Entry entry = ThingsModConfig.Entries[i];
				bool flag2;
				if (entry.Default is bool)
				{
					int num = Values[i];
					bool flag = (uint)num <= 1u;
					flag2 = !flag;
				}
				else
				{
					flag2 = Values[i] < entry.Min || Values[i] > entry.Max;
				}
				if (flag2)
				{
					return false;
				}
				if (Values[i] != 1)
				{
					continue;
				}
				string slot = entry.Slot;
				if (slot != null && entry.Key.EndsWith("Forced", StringComparison.Ordinal))
				{
					string key = entry.Key;
					int num = "Forced".Length;
					string enabled = key.Substring(0, key.Length - num) + "Enabled";
					int num2 = ThingsModConfig.Entries.ToList().FindIndex((ThingsModConfig.Entry candidate) => candidate.Key == enabled);
					if (!hashSet.Add(slot) || num2 < 0 || Values[num2] != 1)
					{
						return false;
					}
				}
			}
			return true;
		}
	}
