		public static bool HasBossWeightOverrides(string slot)
		{
			string slot2 = slot;
			return Entries.Any((Entry entry) => entry.Slot == slot2 && entry.Default is int && GetInt(entry.Key) != (int)entry.Default);
		}

		public static string? GetForcedBossKeyForSlot(string slot)
		{
			foreach (Entry entry in Entries)
			{
				if (!(entry.Slot != slot) && entry.Key.EndsWith("Forced", StringComparison.Ordinal) && IsForced(entry.Key))
				{
					return entry.Key;
				}
			}
			return null;
		}

		public static bool CanForce(string forcedKey)
		{
			string forcedKey2 = forcedKey;
			string text = Entries.FirstOrDefault((Entry candidate) => candidate.Key == forcedKey2)?.Slot;
			if (text == null)
			{
				return false;
			}
			string forcedBossKeyForSlot = GetForcedBossKeyForSlot(text);
			if (forcedBossKeyForSlot != null)
			{
				return forcedBossKeyForSlot == forcedKey2;
			}
			return true;
		}

		public static void Load()
		{
			Dictionary<string, object> previous = new Dictionary<string, object>(Values);
			Values.Clear();
			foreach (Entry entry in Entries)
			{
				Values[entry.Key] = entry.Default;
			}
			string configPath = ConfigPath;
			bool flag = !File.Exists(configPath);
			if (File.Exists(configPath))
			{
				try
				{
					using JsonDocument jsonDocument = JsonDocument.Parse(File.ReadAllText(configPath));
					if (jsonDocument.RootElement.ValueKind != JsonValueKind.Object)
					{
						throw new JsonException("Configuration root must be an object.");
					}
					flag |= jsonDocument.RootElement.EnumerateObject().Any((JsonProperty property) => property.Value.ValueKind != JsonValueKind.String);
					foreach (Entry entry2 in Entries)
					{
						if (jsonDocument.RootElement.TryGetProperty(entry2.Key, out var value) && TryNormalize(entry2, value, out object normalized))
						{
							Values[entry2.Key] = normalized;
						}
						else
						{
							flag = true;
						}
					}
				}
				catch (Exception ex)
				{
					flag = true;
					foreach (Entry entry3 in Entries)
					{
						Values[entry3.Key] = entry3.Default;
					}
					Log.Warn($"STS2_Things config '{configPath}' is unreadable ({ex.Message}); backing it up and using defaults.", 2);
					try
					{
						File.Copy(configPath, configPath + ".corrupt-" + DateTime.Now.ToString("yyyyMMddHHmmss"), overwrite: true);
					}
					catch
					{
					}
				}
			}
			if (flag | ResolveConflicts(logWarnings: true))
			{
				Save();
			}
			if (Values.Any<KeyValuePair<string, object>>((KeyValuePair<string, object> pair) => !previous.TryGetValue(pair.Key, out object value2) || !object.Equals(value2, pair.Value)))
			{
				ThingsModConfig.LocalChanged?.Invoke();
				ThingsModConfig.Changed?.Invoke();
			}
		}

		public static void Save()
		{
			try
			{
				Directory.CreateDirectory(Path.GetDirectoryName(ConfigPath));
				Dictionary<string, string> dictionary = Values.ToDictionary<KeyValuePair<string, object>, string, string>((KeyValuePair<string, object> pair) => pair.Key, (KeyValuePair<string, object> pair) => Convert.ToString(pair.Value, CultureInfo.InvariantCulture));
				dictionary["SchemaVersion"] = "2";
				string text = ConfigPath + ".things-new";
				File.WriteAllText(text, JsonSerializer.Serialize(dictionary, JsonOptions));
				File.Move(text, ConfigPath, overwrite: true);
			}
			catch (Exception ex)
			{
				Log.Warn("STS2_Things config could not be saved: " + ex.Message, 2);
			}
		}

		public static object? GetValue(string key)
		{
			return MultiplayerConfig.GetOverride(key) ?? GetLocalValue(key);
		}

		public static void SetValue(string key, object? value)
		{
			SetValues(new Dictionary<string, object> { [key] = value });
		}

		public static void SetValues(IDictionary<string, object?> changes)
		{
			bool flag = false;
			foreach (KeyValuePair<string, object> change in changes)
			{
				change.Deconstruct(out var key2, out var value);
				string key = key2;
				object value2 = value;
				Entry entry = Entries.FirstOrDefault((Entry candidate) => candidate.Key == key);
				if ((object)entry != null && CanEdit(key) && TryNormalize(entry, value2, out object normalized) && !object.Equals(Values[key], normalized))
				{
					Values[key] = normalized;
					flag = true;
				}
			}
			if (flag)
			{
				ResolveConflicts(logWarnings: true);
				ThingsModConfig.LocalChanged?.Invoke();
				ThingsModConfig.Changed?.Invoke();
			}
		}

		private static bool TryNormalize(Entry entry, object? value, out object normalized)
		{
			normalized = entry.Default;
			if (value is JsonElement jsonElement)
			{
				object obj;
				switch (jsonElement.ValueKind)
				{
				case JsonValueKind.True:
					obj = true;
					break;
				case JsonValueKind.False:
					obj = false;
					break;
				case JsonValueKind.String:
					obj = jsonElement.GetString();
					break;
				case JsonValueKind.Number:
				{
					if (jsonElement.TryGetDouble(out var value2))
					{
						obj = value2;
						break;
					}
					goto default;
				}
				default:
					obj = null;
					break;
				}
				value = obj;
			}
			if (entry.Default is bool)
			{
				if (value is bool flag)
				{
					normalized = flag;
				}
				else
				{
					if (!(value is string value3) || !bool.TryParse(value3, out var result))
					{
						return false;
					}
					normalized = result;
				}
				return true;
			}
			if ((!(value is byte) && !(value is short) && !(value is int) && !(value is long) && !(value is float) && !(value is double) && !(value is decimal) && !(value is string)) || 1 == 0)
			{
				return false;
			}
			if (!double.TryParse(Convert.ToString(value, CultureInfo.InvariantCulture), NumberStyles.Float, CultureInfo.InvariantCulture, out var result2) || !double.IsFinite(result2))
			{
				return false;
			}
			normalized = (int)Math.Round(Math.Clamp(result2, entry.Min, entry.Max), MidpointRounding.AwayFromZero);
			return true;
		}

		private static bool ResolveConflicts(bool logWarnings)
		{
			bool result = false;
			foreach (Entry entry in Entries)
			{
				if (!entry.Key.EndsWith("Enabled", StringComparison.Ordinal))
				{
					continue;
				}
				string slot = entry.Slot;
				if (slot == null)
				{
					continue;
				}
				object valueOrDefault = Values.GetValueOrDefault(ForcedKeyFor(slot, entry.Key));
				if (valueOrDefault is bool && (bool)valueOrDefault)
				{
					valueOrDefault = Values[entry.Key];
					if (valueOrDefault is bool && !(bool)valueOrDefault)
					{
						Values[entry.Key] = true;
						result = true;
					}
				}
			}
			string[] array = new string[3] { "overgrowth", "underdocks", "hive" };
			foreach (string text in array)
			{
				string text2 = null;
				foreach (Entry entry2 in Entries)
				{
					if (entry2.Slot != text || !entry2.Key.EndsWith("Forced", StringComparison.Ordinal))
					{
						continue;
					}
					object valueOrDefault = Values[entry2.Key];
					if (!(valueOrDefault is bool) || !(bool)valueOrDefault)
					{
						continue;
					}
					if (text2 == null)
					{
						text2 = entry2.Key;
						continue;
					}
					Values[entry2.Key] = false;
					result = true;
					if (logWarnings)
					{
						Log.Warn($"STS2_Things config: '{entry2.Key}' was demoted because '{text2}' is already forced for the same act boss slot ({text}).", 2);
					}
				}
			}
			return result;
		}

		private static string ForcedKeyFor(string slot, string enabledKey)
		{
			int length = "Enabled".Length;
			return enabledKey.Substring(0, enabledKey.Length - length) + "Forced";
		}
	}
