		public static void RemoveCreatureWithoutDeathOrEscape(Creature creature)
		{
			if (creature.IsDead)
			{
				return;
			}
			ICombatState combatState = creature.CombatState;
			if (combatState == null || !combatState.IsLiveCombat() || !combatState.ContainsCreature(creature))
			{
