			}
			creature.RemoveAllPowersInternalExcept((IEnumerable<PowerModel>)null);
			NCombatRoom instance = NCombatRoom.Instance;
			NCreature val = ((instance != null) ? instance.GetCreatureNode(creature) : null);
			if (val != null)
			{
