	[HarmonyPatch]
	public static class DrawFromDiscardPatch
	{
		[HarmonyTargetMethod]
		public static MethodBase Target(HarmonyPatchType _, Harmony __)
		{
			return typeof(CardPileCmd).GetMethod("Draw", BindingFlags.Static | BindingFlags.Public, null, new Type[4]
			{
				typeof(PlayerChoiceContext),
				typeof(decimal),
				typeof(Player),
				typeof(bool)
			}, null) ?? throw new MissingMethodException(typeof(CardPileCmd).FullName, "Draw");
		}

		private static bool Prefix(PlayerChoiceContext choiceContext, decimal count, Player player, bool fromHandDraw, ref Task<IEnumerable<CardModel>> __result)
		{
			if (player.Creature.GetPower<ThingsRecallPower>() == null)
			{
				return true;
			}
			if (PileTypeExtensions.GetPile((PileType)3, player).Cards.Count == 0)
			{
				return true;
			}
			__result = DrawFromDiscardThenFallback(choiceContext, count, player, fromHandDraw);
			return false;
		}

		private static async Task<IEnumerable<CardModel>> DrawFromDiscardThenFallback(PlayerChoiceContext choiceContext, decimal count, Player player, bool fromHandDraw)
		{
			if (CombatManager.Instance.IsOverOrEnding)
			{
				return Array.Empty<CardModel>();
			}
			ICombatState combatState = player.Creature.CombatState;
			if (combatState == null)
			{
				return Array.Empty<CardModel>();
			}
			AbstractModel val = default(AbstractModel);
			if (!Hook.ShouldDraw(combatState, player, fromHandDraw, ref val))
			{
				if (val != null)
				{
					await Hook.AfterPreventingDraw(combatState, val);
				}
				return Array.Empty<CardModel>();
			}
			CardPile hand = PileTypeExtensions.GetPile((PileType)2, player);
			CardPile discardPile = PileTypeExtensions.GetPile((PileType)3, player);
			CardPile drawPile = PileTypeExtensions.GetPile((PileType)1, player);
			int drawsRequested = ((count > 0m) ? ((int)Math.Ceiling(count)) : 0);
			List<CardModel> result = new List<CardModel>();
			for (int i = 0; i < drawsRequested; i++)
			{
				if (CombatManager.Instance.IsOverOrEnding)
				{
					break;
				}
				if (hand.Cards.Count >= CardPile.MaxCardsInHand)
				{
					break;
				}
				CardModel card = (CardModel)((discardPile.Cards.Count <= 0) ? ((object)drawPile.Cards.FirstOrDefault()) : ((object)player.RunState.Rng.CombatCardSelection.NextItem<CardModel>((IEnumerable<CardModel>)discardPile.Cards)));
				if (card == null)
				{
					break;
				}
				result.Add(card);
				await CardPileCmd.Add(card, hand, (CardPilePosition)1, (AbstractModel)null, false);
				CombatManager.Instance.History.CardDrawn(combatState, card, fromHandDraw);
				await Hook.AfterCardDrawn(combatState, choiceContext, card, fromHandDraw);
				card.InvokeDrawn();
				NDebugAudioManager instance = NDebugAudioManager.Instance;
				if (instance != null)
				{
					instance.Play("card_deal.mp3", 0.25f, (PitchVariance)1);
				}
			}
			return result;
		}
	}
	public static class LanternBlindness
	{
		private sealed record MarkedCard(ICombatState Combat, int? RolledCost);

		private static readonly ConditionalWeakTable<CardModel, MarkedCard> Marks = new ConditionalWeakTable<CardModel, MarkedCard>();

		public static bool IsBlinded(CardModel? card)
		{
			if (CombatManager.Instance.IsInProgress && card != null && ((AbstractModel)card).IsMutable && Marks.TryGetValue(card, out MarkedCard value))
			{
				return card.CombatState == value.Combat;
			}
			return false;
		}

		public static void Mark(CardModel card, int? rolledCost)
		{
			ICombatState combatState = card.CombatState;
			if (combatState != null)
			{
				Marks.Remove(card);
				Marks.Add(card, new MarkedCard(combatState, rolledCost));
			}
		}

		public static void Forget(CardModel card)
		{
			Marks.Remove(card);
		}

		internal static void Copy(CardModel source, CardModel clone)
		{
			if (IsBlinded(source) && Marks.TryGetValue(source, out MarkedCard value))
			{
				Marks.Remove(clone);
				Marks.Add(clone, value);
			}
		}
	}
