	public static class SfxHooks
	{
		[HarmonyPatch(typeof(SfxCmd), "Play", new Type[]
		{
			typeof(string),
			typeof(float)
		})]
		public static class SfxCmdPlayPatch
		{
			[HarmonyPrefix]
			public static bool Prefix(ref string sfx, float volume)
			{
				if (sfx == null)
				{
					return true;
				}
				HashSet<string> entries = CustomSfxMonsters.Entries;
				if (entries.Count == 0)
				{
					return true;
				}
				foreach (string item in entries)
				{
					if (sfx.IndexOf(item, StringComparison.OrdinalIgnoreCase) >= 0)
					{
						if (!CanPlayCombatAudio() || !float.IsFinite(volume) || volume <= 0f)
						{
							return false;
						}
						string text = MapToNativePath(sfx);
						if (text != null)
						{
							NativeSfxPlayer.Play(text, "Master", Mathf.LinearToDb(volume));
						}
						return false;
					}
				}
				return true;
			}
		}

		[HarmonyPatch(typeof(SfxCmd), "PlayDamage")]
		public static class SfxCmdPlayDamagePatch
		{
			[HarmonyPrefix]
			public static bool Prefix(MonsterModel? monster, int damageAmount)
			{
				if (monster == null)
				{
					return true;
				}
				string text = ((AbstractModel)monster).Id.Entry.ToLowerInvariant();
				if (!CustomSfxMonsters.Entries.Contains(text))
				{
					return true;
				}
				if (!CanPlayCombatAudio())
				{
					return false;
				}
				if (text == "origin_fogmog" && !NativeSfxPlayer.RollChance(0.35f))
				{
					return true;
				}
				string text2 = MapToNativePathForMonster(text, "hurt");
				if (text2 != null)
				{
					NativeSfxPlayer.Play(text2, "Master", 0f);
				}
				return false;
			}
		}

		[HarmonyPatch(typeof(SfxCmd), "PlayDeath", new Type[] { typeof(MonsterModel) })]
