		{
			[HarmonyPrefix]
			public static bool Prefix(MonsterModel? monster)
			{
				if (monster == null)
				{
					return true;
				}
				string text = ((AbstractModel)monster).Id.Entry.ToLowerInvariant();
				string text2 = (CustomSfxMonsters.Entries.Contains(text) ? MapToNativePathForMonster(text, "die") : ((((object)monster).GetType().Assembly == typeof(SfxHooks).Assembly) ? MapToNativePath(monster.DeathSfx) : null));
				if (text2 == null)
				{
					return true;
				}
				if (!CanPlayDeathAudio())
				{
					return false;
