		private static string? MapToNativePath(string fmodPath)
		{
			string fmodPath2 = fmodPath;
			string[] array = fmodPath2.Split('/');
			if (array.Length < 2)
			{
				return null;
			}
			string text = array[^1];
			string text2 = CustomSfxMonsters.Entries.FirstOrDefault((string e) => fmodPath2.ToLowerInvariant().Contains(e));
			if (text2 == null)
			{
				return null;
			}
			return "res://sfx/" + text2 + "/" + text;
		}

		private static string MapToNativePathForMonster(string monsterId, string actionName)
		{
			return $"res://sfx/{monsterId}/{monsterId}_{actionName}";
		}

		public static IEnumerable<string> GetMonsterSoundAssetPaths(string monsterId)
		{
			if (!CustomSfxMonsters.Entries.Contains(monsterId))
			{
				return Array.Empty<string>();
			}
			string text = "res://sfx/" + monsterId;
			List<string> list = ListAudioFiles(text);
			if (list.Count == 0)
			{
				string path2 = Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location) ?? AppContext.BaseDirectory, "sfx", monsterId);
				if (Directory.Exists(path2))
				{
					string[] files = Directory.GetFiles(path2);
					foreach (string text2 in files)
					{
						if (IsAudioFile(text2))
						{
							list.Add(text + "/" + Path.GetFileName(text2));
						}
					}
				}
			}
			return list.Where((string path) => ResourceLoader.Exists(path, "")).Distinct<string>(StringComparer.Ordinal).Order<string>(StringComparer.Ordinal);
		}

		private static List<string> ListAudioFiles(string resDir)
		{
			//IL_0013: Unknown result type (might be due to invalid IL or missing references)
			List<string> list = new List<string>();
			DirAccess val = DirAccess.Open(resDir);
			if (val == null)
			{
				return list;
			}
			val.ListDirBegin();
			string next = val.GetNext();
			while (next != string.Empty)
			{
				string text;
				if (!next.EndsWith(".import", StringComparison.Ordinal))
				{
					if (!next.EndsWith(".remap", StringComparison.Ordinal))
					{
						text = next;
					}
					else
					{
						string text2 = next;
						text = text2.Substring(0, text2.Length - 6);
					}
				}
				else
				{
					string text2 = next;
					text = text2.Substring(0, text2.Length - 7);
				}
				string text3 = text;
				if (!val.CurrentIsDir() && IsAudioFile(text3))
				{
					list.Add(resDir + "/" + text3);
				}
				next = val.GetNext();
			}
			val.ListDirEnd();
			return list;
		}

		private static bool IsAudioFile(string fileName)
		{
			if (!fileName.Contains('.'))
			{
				return false;
			}
			int num = fileName.LastIndexOf('.');
			string text = fileName.Substring(num, fileName.Length - num).ToLowerInvariant();
			if (!(text == ".ogg") && !(text == ".wav"))
			{
				return text == ".mp3";
			}
			return true;
		}
