			List<TModel> list4 = list.Where((TModel model) => ((object)model).GetType().Assembly == AssemblyInfo.BaseGame).ToList();
			foreach (Item<ModelId> item in list3)
			{
				list4.Add(dictionary[item.type].Dequeue());
			}
			return list4;
		}

		public static IEnumerable<TModel> SortNativePool<TModel>(AbstractModel pool, IEnumerable<TModel> source) where TModel : AbstractModel
