	public static class EncounterSelectionPolicy
	{
		private static readonly Action<ICollection<EncounterModel>, GrabBag<EncounterModel>, Rng> VanillaDraw = AccessTools.Method(typeof(ActModel), "AddWithoutRepeatingTags", (Type[])null, (Type[])null).CreateDelegate<Action<ICollection<EncounterModel>, GrabBag<EncounterModel>, Rng>>();

		public static string? EnabledKey(EncounterModel encounter)
		{
			if (!(encounter is OriginFogmogBossEncounter))
			{
				if (!(encounter is ScaleBeetleBossEncounter))
				{
					if (!(encounter is GravetideSlugBossEncounter))
					{
						if (!(encounter is TheLegacyBossEncounter))
						{
							if (!(encounter is BowlbugProgenitorBossEncounter))
							{
								if (!(encounter is CaveGodBossEncounter))
								{
									if (!(encounter is SoulRoesEncounter))
									{
										if (encounter is QuirkyHopperWeak)
										{
											return "EncounterQuirkyHopperEnabled";
										}
										return null;
									}
									return "EncounterSoulRoesEnabled";
								}
								return "BossCaveGodEnabled";
							}
							return "BossBowlbugProgenitorEnabled";
						}
						return "BossTheLegacyEnabled";
					}
					return "BossGravetideSlugEnabled";
				}
				return "BossScaleBeetleEnabled";
			}
			return "BossOriginFogmogEnabled";
		}

		public static string? WeightKey(EncounterModel encounter)
		{
			if (!(encounter is OriginFogmogBossEncounter))
			{
				if (!(encounter is ScaleBeetleBossEncounter))
				{
					if (!(encounter is GravetideSlugBossEncounter))
					{
						if (!(encounter is TheLegacyBossEncounter))
						{
							if (!(encounter is BowlbugProgenitorBossEncounter))
							{
								if (!(encounter is CaveGodBossEncounter))
								{
									if (encounter is SoulRoesEncounter)
									{
										return "EncounterSoulRoesWeightPercent";
									}
									return null;
								}
								return "BossCaveGodWeightPercent";
							}
							return "BossBowlbugProgenitorWeightPercent";
						}
						return "BossTheLegacyWeightPercent";
					}
					return "BossGravetideSlugWeightPercent";
				}
				return "BossScaleBeetleWeightPercent";
			}
			return "BossOriginFogmogWeightPercent";
		}

		public static string? ForcedKey(EncounterModel encounter)
		{
			if (IsOwnedBoss(encounter))
			{
				string text = EnabledKey(encounter);
				if (text != null)
				{
					string text2 = text;
					int length = "Enabled".Length;
					return text2.Substring(0, text2.Length - length) + "Forced";
				}
			}
			return null;
		}

		public static bool IsOwnedBoss(EncounterModel encounter)
		{
			if (encounter is ModBossEncounter)
			{
				return ((object)encounter).GetType().Assembly == typeof(EncounterSelectionPolicy).Assembly;
			}
			return false;
		}

		public static string? Slot(ActModel act)
		{
			if (!(act is Overgrowth))
			{
				if (!(act is Underdocks))
				{
					if (act is Hive)
					{
						return "hive";
					}
					return null;
				}
				return "underdocks";
			}
			return "overgrowth";
		}

		public static bool IsAvailable(EncounterModel encounter)
		{
			string text = EnabledKey(encounter);
			if (text != null)
			{
				if (ThingsModConfig.IsEnabled(text))
				{
					return GetWeight(encounter) > 0.0;
				}
				return false;
			}
			return true;
		}

		public static double GetWeight(EncounterModel encounter)
		{
			string text = ForcedKey(encounter);
			if (text != null && ThingsModConfig.IsForced(text))
			{
				return 1.0;
			}
			string text2 = WeightKey(encounter);
			if (text2 == null)
			{
				return 1.0;
			}
			return (double)ThingsModConfig.GetInt(text2) / 100.0;
		}

		public static EncounterModel? ChooseBoss(Rng rng, IEnumerable<EncounterModel> source)
		{
			EncounterModel[] array = source.ToArray();
			if (array.All((EncounterModel encounter) => GetWeight(encounter) == 1.0))
			{
				return rng.NextItem<EncounterModel>((IEnumerable<EncounterModel>)array);
			}
			GrabBag<EncounterModel> val = new GrabBag<EncounterModel>();
			EncounterModel[] array2 = array;
			foreach (EncounterModel val2 in array2)
			{
				double weight = GetWeight(val2);
				if (weight > 0.0)
				{
					val.Add(val2, weight);
				}
			}
			if (!val.Any())
			{
				return null;
			}
			return val.Grab(rng, (Func<EncounterModel, bool>)null);
		}

		public static void AddWeighted(GrabBag<EncounterModel> bag, EncounterModel encounter, double weight)
		{
			double num = weight * GetWeight(encounter);
			if (num > 0.0)
			{
				bag.Add(encounter, num);
			}
		}

		public static void DrawElite(ICollection<EncounterModel> encounters, GrabBag<EncounterModel> bag, Rng rng, ActModel act)
		{
			int @int = ThingsModConfig.GetInt("EncounterSoulRoesWeightPercent");
			bool flag = ((@int == 0 || @int == 100) ? true : false);
			if (flag || !act.AllEliteEncounters.Any((EncounterModel encounter) => encounter is SoulRoesEncounter))
			{
				VanillaDraw(encounters, bag, rng);
				return;
			}
			EncounterModel last = encounters.LastOrDefault();
			EncounterModel val = bag.Grab(rng, (Func<EncounterModel, bool>)((EncounterModel encounter) => !encounter.SharesTagsWith(last) && encounter != last)) ?? bag.Grab(rng, (Func<EncounterModel, bool>)null);
			if (val != null)
			{
				encounters.Add(val);
			}
		}
	}
